function longestBalancedRun(bits: number[]): number {
  let best = 0;
  for (let i = 0; i < bits.length; i++) {
    let score = 0;
    for (let j = i; j < bits.length; j++) {
      score += bits[j] === 1 ? 1 : -1;
      if (score === 0) best = Math.max(best, j - i + 1);
    }
  }
  return best;
}

