function longestBalancedRun(bits: number[]): number {
  const first = new Map<number, number>([[0, -1]]);
  let score = 0, best = 0;
  for (let j = 0; j < bits.length; j++) {
    score += bits[j] === 1 ? 1 : -1;
    const i = first.get(score);
    if (i === undefined) first.set(score, j);
    else best = Math.max(best, j - i);
  }
  return best;
}

